457	function checkpointDocument(order = CHECKPOINT_SECTION_NAMES, prelude = []) {
458	  return [
459	    "# Handoff",
460	    "",
461	    ...prelude,
462	    ...(prelude.length === 0 ? [] : [""]),
463	    ...order.flatMap((name) => [`## ${name}`, "", sectionBody(name), ""]),
464	  ].join("\n");
465	}
466	
467	function sectionBody(name) {
468	  return `verified ${name.toLowerCase()} content`;
469	}
