507	async function git(root, arguments_) {
508	  await execFileAsync("git", arguments_, {
509	    cwd: root,
510	    encoding: "utf8",
511	    env: { ...process.env, GIT_OPTIONAL_LOCKS: "0", LC_ALL: "C" },
512	  });
513	}
