515	async function runCli(arguments_) {
516	  return await new Promise((resolve, reject) => {
517	    const child = spawn(process.execPath, [cli, ...arguments_], {
518	      cwd: path.dirname(cli),
519	      env: { ...process.env, NO_COLOR: "1" },
520	    });
521	    let stdout = "";
522	    let stderr = "";
523	    child.stdout.setEncoding("utf8").on("data", (chunk) => {
524	      stdout += chunk;
525	    });
526	    child.stderr.setEncoding("utf8").on("data", (chunk) => {
527	      stderr += chunk;
528	    });
529	    child.on("error", reject);
530	    child.on("close", (code) => resolve({ code, stdout, stderr }));
531	  });
532	}
