534	function findForbiddenMetadataKeys(value, pathParts = []) {
535	  if (value === null || typeof value !== "object") return [];
536	  const findings = [];
537	  for (const [key, nested] of Object.entries(value)) {
538	    const current = [...pathParts, key];
539	    if (/^(?:committedAt|timestamp|sessionId|absolutePath|root)$/i.test(key)) {
540	      findings.push(current.join("."));
541	    }
542	    findings.push(...findForbiddenMetadataKeys(nested, current));
543	  }
544	  return findings;
545	}
